import{_t as e,it as t,n,rt as r}from"./chunks/framework.D72WcpWg.js";var i=JSON.parse(`{"title":"Server-Side Rendering","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/ssr.md","filePath":"getting-started/ssr.md","lastUpdated":1792228114000}`),a={name:`getting-started/ssr.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="server-side-rendering" tabindex="-1">Server-Side Rendering <a class="header-anchor" href="#server-side-rendering" aria-label="Permalink to “Server-Side Rendering”">​</a></h1><p>The module works on a server-rendered page: every input and output type renders on the server and hydrates without a warning. This is checked, not assumed - the playground is loaded with server rendering on, in <code>nuxi dev</code> and in a production build, with the server and the browser deliberately in time zones 26 hours apart, and it fails on any hydration warning, console error, Vue warning or error in the server log (<code>npm run test:e2e:ssr</code> in the repository).</p><p>Server rendering is off in the playground by default; set <code>PLAYGROUND_SSR=true</code> to turn it on.</p><h2 id="what-the-server-renders" tabindex="-1">What the server renders <a class="header-anchor" href="#what-the-server-renders" aria-label="Permalink to “What the server renders”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>On the server</th><th>After hydration</th></tr></thead><tbody><tr><td>Field chrome (label, help text, messages)</td><td>rendered</td><td>unchanged</td></tr><tr><td>Every input and output type</td><td>rendered</td><td>unchanged</td></tr><tr><td><code>nuxtUIEditor</code></td><td>label and help text only</td><td>the editor, its toolbar and its content</td></tr><tr><td><code>nuxtUIMultiStep</code> / <code>nuxtUIStep</code></td><td>the step panels and their fields; <strong>not the tab strip</strong></td><td>the tab strip</td></tr><tr><td><code>FUDataEdit</code> <code>autosave</code></td><td>the form, without a draft</td><td>a stored draft is restored into the inputs</td></tr><tr><td>Date and calendar fields</td><td>the day in the <strong>server&#39;s</strong> time zone</td><td>the day in the <strong>browser&#39;s</strong> time zone</td></tr></tbody></table><p>None of these cause a hydration mismatch. The rows that differ before and after hydration are described below.</p><h2 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to “The editor”">​</a></h2><p><code>UEditor</code> is built in the browser, so the server leaves the editor&#39;s place empty and it appears after hydration. The content below an editor therefore moves down when it mounts (about 73px in the default theme). If that matters on your page, reserve the space with a minimum height on the field:</p><div class="language-ts line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$formkit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;nuxtUIEditor&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;body&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Body&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">outerClass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;min-h-[113px]&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="multi-step-forms" tabindex="-1">Multi-step forms <a class="header-anchor" href="#multi-step-forms" aria-label="Permalink to “Multi-step forms”">​</a></h2><p>The step panels and the fields in them are server-rendered, so the form is readable without JavaScript, but the tab strip is built in the browser. It appears right after hydration.</p><h2 id="date-and-calendar-fields" tabindex="-1">Date and calendar fields <a class="header-anchor" href="#date-and-calendar-fields" aria-label="Permalink to “Date and calendar fields”">​</a></h2><p>A JavaScript <code>Date</code> or an ISO string with a time zone is an instant, not a calendar day: which day it shows depends on the zone it is shown in, and the server cannot know the browser&#39;s. So the server renders the day in its own zone, the browser hydrates with the same zone, and the field switches to the browser&#39;s own zone right after mount. A visitor in another zone sees the day change once, immediately after the page loads - there is no hydration mismatch, and the form value is not changed by it.</p><p>To show the same day everywhere, give the field an explicit zone, which is never switched:</p><div class="language-ts line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$formkit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;nuxtUIInputDate&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;start&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Start&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">valueType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;date&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timeZone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;UTC&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>A calendar with no value is centred on today in the same zone, so it follows the same rule. A calendar or date field holding a plain day (<code>&#39;2026-07-05&#39;</code> or a <code>CalendarDate</code>) has no zone and is never affected.</p><div class="warning custom-block"><p class="custom-block-title">Build dates from ISO strings or <code>Date.UTC</code>, not from local parts</p><p>In a page that is server-rendered, the page&#39;s script runs twice - on the server and in the browser. <code>new Date(2026, 6, 5)</code> is <em>local</em> midnight, so it is a different instant in each place, and the field will hydrate with a different day. Use <code>new Date(Date.UTC(2026, 6, 5, 12))</code>, an ISO string, or a <code>CalendarDate</code>.</p></div><h2 id="overlays" tabindex="-1">Overlays <a class="header-anchor" href="#overlays" aria-label="Permalink to “Overlays”">​</a></h2><p><code>useFormKitOverlay().edit()</code> and <code>.auto()</code> need a user to answer them, so they cannot run on the server: the promise would never settle and an <code>await</code> in an async <code>setup</code> would hang the request. They throw an error that says so. Call them from an event handler or <code>onMounted</code>; creating the composable itself is safe anywhere.</p><h2 id="autosave" tabindex="-1">Autosave <a class="header-anchor" href="#autosave" aria-label="Permalink to “Autosave”">​</a></h2><p><code>autosave</code> needs no special handling. On the server the plugin does nothing; in the browser it restores a stored draft after hydration, so the first render matches the server&#39;s and the draft appears as an ordinary update.</p><h2 id="checking-your-own-app" tabindex="-1">Checking your own app <a class="header-anchor" href="#checking-your-own-app" aria-label="Permalink to “Checking your own app”">​</a></h2><p>Vue only compares attributes during hydration in a <strong>development</strong> build; a production build silently keeps whatever the server rendered. So check for hydration warnings with <code>nuxi dev</code>, where <code>Hydration attribute mismatch</code> and <code>Hydration text mismatch</code> are reported. If you add a page to the playground it is covered automatically.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};